initJs:
function(container, apiUrl, tables) {
  let currentProducts = [];
  let stores = [];
  let predictions = [];
  let orders = [];

  // 店舗データとその他データの初期化
  async function initializeData() {
    try {
      stores = await window.aivicApi.list(1) || []; // 店舗マスタ
      predictions = await window.aivicApi.list(8) || []; // 需要予測結果
      orders = await window.aivicApi.list(9) || []; // 発注データ

      // 店舗選択肢を設定
      const storeSelect = container.querySelector("#select-store");
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
      stores.filter(s => s.有効フラグ).forEach(store => {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      });
    } catch (error) {
      console.error("データ初期化エラー:", error);
    }
  }

  // 商品一覧の再描画
  function renderProducts(products) {
    const tbody = container.querySelector("#product-tbody");
    const tableContainer = container.querySelector("#table-container");
    const noStoreMessage = container.querySelector("#no-store-message");
    const bulkOrderBtn = container.querySelector("#btn-bulk-order");

    if (!products || products.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted); padding: 20px;">該当する商品がありません</td></tr>';
      bulkOrderBtn.disabled = true;
      return;
    }

    tableContainer.classList.remove("hidden");
    noStoreMessage.classList.add("hidden");
    bulkOrderBtn.disabled = false;

    tbody.innerHTML = products.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector("#select-store").value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const recommendedQty = prediction ? prediction.推奨発注数量 : 0;
      const currentStock = Math.floor(Math.random() * 100) + 10; // 仮の在庫数

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td style="color: var(--text);">${product.商品コード || ""}</td>
          <td style="color: var(--text);">${product.商品名 || ""}</td>
          <td style="color: var(--text-muted);">${getProductCategory(product.商品カテゴリID)}</td>
          <td style="color: var(--text);">${currentStock}</td>
          <td style="color: var(--text);">${predictedQty}</td>
          <td style="color: var(--text); font-weight: bold;">${recommendedQty}</td>
          <td>
            <input type="number" class="input order-quantity" data-id="${product.商品ID}" 
                   value="${recommendedQty}" min="0" style="width: 80px;">
            <button class="action-btn secondary adjust-btn" data-id="${product.商品ID}" data-action="use-recommended">推奨</button>
          </td>
          <td>
            <input type="text" class="input order-reason" data-id="${product.商品ID}" 
                   placeholder="発注理由" style="width: 120px;">
          </td>
          <td>
            <button class="action-btn order-btn" data-id="${product.商品ID}">発注</button>
            <button class="action-btn secondary" onclick="window.showScreen('scr-1778591896813')">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 商品カテゴリ名を取得（仮実装）
  function getProductCategory(categoryId) {
    const categories = {
      "cat1": "食品",
      "cat2": "日用品", 
      "cat3": "衣料品",
      "cat4": "家電"
    };
    return categories[categoryId] || "その他";
  }

  // 検索・絞り込み処理
  async function searchProducts() {
    const storeId = container.querySelector("#select-store").value;
    const category = container.querySelector("#select-category").value;
    const dateStart = container.querySelector("#input-date-start").value;
    const dateEnd = container.querySelector("#input-date-end").value;
    const searchKeyword = container.querySelector("#input-search").value.toLowerCase();

    // 日付バリデーション
    if (dateStart && dateEnd && new Date(dateStart) > new Date(dateEnd)) {
      showError("終了日は開始日以降の日付を入力してください");
      return;
    }

    if (!storeId) {
      container.querySelector("#table-container").classList.add("hidden");
      container.querySelector("#no-store-message").classList.remove("hidden");
      return;
    }

    try {
      const allProducts = await window.aivicApi.list(2) || []; // 商品マスタ
      let filteredProducts = allProducts.filter(p => p.有効フラグ);

      // カテゴリ絞り込み
      if (category) {
        filteredProducts = filteredProducts.filter(p => getProductCategory(p.商品カテゴリID) === category);
      }

      // 商品名検索
      if (searchKeyword) {
        filteredProducts = filteredProducts.filter(p => 
          (p.商品名 || "").toLowerCase().includes(searchKeyword) ||
          (p.商品コード || "").toLowerCase().includes(searchKeyword)
        );
      }

      currentProducts = filteredProducts;
      renderProducts(filteredProducts);
      hideError();

      // 需要予測結果の表示
      showPredictionResults(storeId, filteredProducts);

    } catch (error) {
      console.error("検索エラー:", error);
      showError("検索中にエラーが発生しました");
    }
  }

  // 需要予測結果表示
  function showPredictionResults(storeId, products) {
    const predictionArea = container.querySelector("#prediction-area");
    const predictionContent = container.querySelector("#prediction-content");

    if (products.length === 0) {
      predictionArea.classList.add("hidden");
      return;
    }

    const storePredictions = predictions.filter(p => p.店舗ID === storeId);
    const totalPredicted = storePredictions.reduce((sum, p) => sum + (p.予測数量 || 0), 0);
    const totalRecommended = storePredictions.reduce((sum, p) => sum + (p.推奨発注数量 || 0), 0);

    predictionContent.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px;">
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalPredicted}</div>
          <div style="color: var(--text-muted);">総予測需要量</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--primary);">${totalRecommended}</div>
          <div style="color: var(--text-muted);">総推奨発注量</div>
        </div>
        <div style="text-align: center;">
          <div style="font-size: 24px; font-weight: bold; color: var(--text);">${products.length}</div>
          <div style="color: var(--text-muted);">対象商品数</div>
        </div>
      </div>
    `;

    predictionArea.classList.remove("hidden");
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    errorDiv.textContent = message;
    errorDiv.classList.remove("hidden");
  }

  function hideError() {
    container.querySelector("#error-message").classList.add("hidden");
  }

  // 発注処理
  async function processOrder(productId, quantity, reason) {
    if (!quantity || quantity <= 0) {
      showError("発注量は正の数値を入力してください");
      return false;
    }

    if (isNaN(quantity)) {
      showError("発注量は数値で入力してください");
      return false;
    }

    const storeId = container.querySelector("#select-store").value;
    const product = currentProducts.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === storeId);

    const orderData = {
      店舗ID: storeId,
      商品ID: productId,
      需要予測結果ID: prediction ? prediction.予測結果ID : null,
      発注日: new Date().toISOString(),
      納期予定日: new Date(Date.now() + (product?.リードタイム日数 || 7) * 24 * 60 * 60 * 1000).toISOString(),
      発注数量: parseInt(quantity),
      予測数量: prediction ? prediction.予測数量 : 0,
      発注単価: product?.単価 || 0,
      発注金額: parseInt(quantity) * (product?.単価 || 0),
      発注方法: prediction && parseInt(quantity) === prediction.推奨発注数量 ? "AI推奨採用" : "AI推奨修正",
      発注ステータス: "発注済",
      仕入先ID: product?.仕入先ID || "",
      発注理由: reason || "",
      自動発注フラグ: false,
      作成者ID: "current-user",
      更新者ID: "current-user"
    };

    try {
      const saved = await window.aivicApi.save(9, orderData);
      if (saved) {
        return true;
      } else {
        showError("発注処理に失敗しました");
        return false;
      }
    } catch (error) {
      console.error("発注エラー:", error);
      showError("発注処理中にエラーが発生しました");
      return false;
    }
  }

  // CSVエクスポート
  function exportCSV() {
    if (currentProducts.length === 0) {
      showError("エクスポートするデータがありません");
      return;
    }

    const headers = ["商品コード", "商品名", "カテゴリ", "現在在庫", "予測需要量", "推奨発注量"];
    const csvContent = "\uFEFF" + [
      headers.join(","),
      ...currentProducts.map(product => {
        const prediction = predictions.find(p => p.商品ID === product.商品ID);
        return [
          `"${product.商品コード || ""}"`,
          `"${product.商品名|| ""}"`,
          `"${getProductCategory(product.商品カテゴリID)}"`,
          Math.floor(Math.random() * 100) + 10,
          prediction ? prediction.予測数量 : 0,
          prediction ? prediction.推奨発注数量 : 0
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `発注管理_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  }

  // 初期化
  initializeData();

  // イベントリスナー
  container.querySelector("#select-store").addEventListener("change", searchProducts);

  container.querySelector("#btn-search").addEventListener("click", searchProducts);

  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#select-store").value = "";
    container.querySelector("#select-category").value = "";
    container.querySelector("#input-date-start").value = "";
    container.querySelector("#input-date-end").value = "";
    container.querySelector("#input-search").value = "";
    container.querySelector("#table-container").classList.add("hidden");
    container.querySelector("#no-store-message").classList.remove("hidden");
    container.querySelector("#prediction-area").classList.add("hidden");
    hideError();
  });

  container.querySelector("#btn-export").addEventListener("click", exportCSV);

  // 全選択チェックボックス
  container.querySelector("#select-all").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".product-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // 一括発注
  container.querySelector("#btn-bulk-order").addEventListener("click", async () => {
    const checkedBoxes = container.querySelectorAll(".product-checkbox:checked");
    if (checkedBoxes.length === 0) {
      showError("発注する商品を選択してください");
      return;
    }

    let successCount = 0;
    for (const checkbox of checkedBoxes) {
      const productId = checkbox.dataset.id;
      const quantityInput = container.querySelector(`input.order-quantity[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-id="${productId}"]`);

      const success = await processOrder(productId, quantityInput.value, reasonInput.value);
      if (success) successCount++;
    }

    if (successCount > 0) {
      alert(`${successCount}件の発注を完了しました`);
      searchProducts(); // 画面更新
    }
  });

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 推奨発注量設定
    if (e.target.classList.contains("adjust-btn")) {
      const productId = e.target.dataset.id;
      const prediction = predictions.find(p => p.商品ID === productId);
      const quantityInput = container.querySelector(`input.order-quantity[data-id="${productId}"]`);
      if (prediction && quantityInput) {
        quantityInput.value = prediction.推奨発注数量 || 0;
      }
    }

    // 個別発注
    if (e.target.classList.contains("order-btn")) {
      const productId = e.target.dataset.id;
      const quantityInput = container.querySelector(`input.order-quantity[data-id="${productId}"]`);
      const reasonInput = container.querySelector(`input.order-reason[data-id="${productId}"]`);

      const product = currentProducts.find(p => p.商品ID === productId);

      // 発注確認モーダル表示
      const modal = container.querySelector("#order-modal");
      const orderDetails = container.querySelector("#order-details");

      orderDetails.innerHTML = `
        <p><strong>商品名:</strong> ${product?.商品名 || ""}</p>
        <p><strong>商品コード:</strong> ${product?.商品コード || ""}</p>
        <p><strong>発注数量:</strong> ${quantityInput.value}</p>
        <p><strong>発注理由:</strong> ${reasonInput.value || "なし"}</p>
      `;

      modal.classList.remove("hidden");

      // 発注確定処理
      const confirmBtn = container.querySelector("#btn-confirm-order");
      const cancelBtn = container.querySelector("#btn-cancel-order");

      const newConfirmHandler = async () => {
        const success = await processOrder(productId, quantityInput.value, reasonInput.value);
        if (success) {
          alert("発注が完了しました");
          modal.classList.add("hidden");
          searchProducts(); // 画面更新
        }
        confirmBtn.removeEventListener("click", newConfirmHandler);
      };

      const newCancelHandler = () => {
        modal.classList.add("hidden");
        cancelBtn.removeEventListener("click", newCancelHandler);
      };

      confirmBtn.addEventListener("click", newConfirmHandler);
      cancelBtn.addEventListener("click", newCancelHandler);
    }
  });

  // 入力値バリデーション
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity")) {
      const value = e.target.value;
      if (value && (isNaN(value) || parseFloat(value) < 0)) {
        e.target.style.borderColor = "#ff6b6b";
        showError("発注量は0以上の数値を入力してください");
      } else {
        e.target.style.borderColor = "";
        hideError();
      }
    }
  });
}
